# Glossaire MEDINA — chapitre I25 (syndromes coronariens chroniques et angor)
from cardio_1 import a, G

def t(k, lit, full, d, ref=None):
    a(k, lit, full, d, ref)

# --- concepts cliniques ---
a('SCC',[('S','Syndrome'),('C','Coronarien'),('C','Chronique')],'Syndrome coronarien chronique',
 '<p>Terme ESC (2019, redéfini en 2024) : présentations dues à des anomalies structurelles ou fonctionnelles des coronaires épicardiques ou de la microcirculation, responsables d’un déséquilibre transitoire et réversible entre apports et besoins en oxygène.</p>')
a('ANOCA',[('A','Angina (angor)'),('NO','with No Obstructive (sans sténose obstructive)'),('C','Coronary (coronaire)'),('A','Arteries (des artères)')],'Angor sans sténose coronaire obstructive',
 '<p>Angor avec des coronaires sans sténose obstructive (&lt; 50 % ou FFR &gt; 0,80). Mécanismes : dysfonction microvasculaire, spasme microvasculaire, vasospasme épicardique.</p>','i25-endotypes')
a('INOCA',[('I','Ischaemia (ischémie)'),('NO','with No Obstructive (sans sténose obstructive)'),('C','Coronary (coronaire)'),('A','Arteries (des artères)')],'Ischémie sans sténose coronaire obstructive',
 '<p>Ischémie myocardique objectivée (imagerie, ECG, tests invasifs) avec des coronaires sans sténose obstructive.</p>','i25-endotypes')
a('RF-CL',[('RF','Risk Factor-weighted (pondérée par les facteurs de risque)'),('C','Clinical (clinique)'),('L','Likelihood (probabilité)')],'Probabilité clinique pondérée par les facteurs de risque',
 '<p>Modèle de l’ESC 2024 qui estime la probabilité de maladie coronaire obstructive à partir du sexe, de l’âge, du type de symptôme et du nombre de facteurs de risque.</p>','i25-rfcl')
a('CACS-CL',[('CACS','Coronary Artery Calcium Score (score calcique coronaire)'),('C','Clinical (clinique)'),('L','Likelihood (probabilité)')],'Probabilité clinique ajustée par le score calcique',
 '<p>Modèle qui combine le RF-CL et le score calcique coronaire ; il classe davantage de patients en probabilité très basse.</p>','i25-cac')
a('IMR',[('I','Index of (indice de)'),('M','Microcirculatory (microcirculatoire)'),('R','Resistance (résistance)')],'Indice de résistance microvasculaire',
 '<p>Pression distale en hyperhémie × temps de transit moyen par thermodilution. ≥ 25 : résistances microvasculaires élevées.</p>','i25-imr')
a('FFR-CT',[('F','Fractional (fractionnelle)'),('F','Flow (du flux)'),('R','Reserve (réserve)'),('CT','Computed Tomography (dérivée du scanner)')],'Réserve coronaire fractionnelle dérivée du coroscanner',
 '<p>FFR calculée par modélisation de l’écoulement à partir des images du coroscanner ; ≤ 0,80 en aval d’une sténose suggère une signification hémodynamique.</p>','i25-ffrct')
a('CAD-RADS',[('CAD','Coronary Artery Disease (maladie coronaire)'),('R','Reporting (compte rendu)'),('A','And (et)'),('D','Data (données)'),('S','System (système)')],'Système standardisé de compte rendu du coroscanner',
 '<p>Classification de la sténose maximale au coroscanner de 0 (aucune plaque) à 5 (occlusion), version 2.0 (2022), avec des modificateurs (charge en plaque, plaque à haut risque, stent, pontage).</p>','i25-ccta')
a('TEP',[('T','Tomographie'),('E','par Émission de'),('P','Positons')],'Tomographie par émission de positons',
 '<p>Imagerie nucléaire qui mesure la perfusion et le débit myocardique absolu (mL/min/g) et la réserve de débit ; utile dans l’ischémie équilibrée et la dysfonction microvasculaire.</p>','i25-stressimg')
a('SPECT',[('S','Single'),('P','Photon'),('E','Emission'),('C','Computed'),('T','Tomography')],'Tomoscintigraphie par émission monophotonique',
 '<p>Scintigraphie de perfusion myocardique : un défaut réversible entre stress et repos signe une ischémie, un défaut fixe une cicatrice.</p>','i25-stressimg')
a('STS',[('S','Society of'),('T','Thoracic'),('S','Surgeons')],'Society of Thoracic Surgeons (score de risque opératoire)',
 '<p>Société américaine de chirurgie thoracique ; son score estime la mortalité opératoire d’un pontage ou d’une chirurgie valvulaire.</p>','i25-heartteam')
a('EuroSCORE II',[('Euro','European (européen)'),('S','System for'),('C','Cardiac'),('O','Operative'),('R','Risk'),('E','Evaluation'),('II','deuxième version')],'Système européen d’évaluation du risque opératoire cardiaque, version II',
 '<p>Score qui estime la mortalité hospitalière après une chirurgie cardiaque à partir de variables cliniques et opératoires.</p>','i25-heartteam')
a('EACTS',[('E','European'),('A','Association for'),('C','Cardio-'),('T','Thoracic'),('S','Surgery')],'European Association for Cardio-Thoracic Surgery (Association européenne de chirurgie cardiothoracique)',
 '<p>Société savante qui a coécrit avec l’ESC les recommandations sur la revascularisation myocardique (2018) et approuvé celles de 2024 sur le SCC.</p>')
a('EAPCI',[('E','European'),('A','Association of'),('P','Percutaneous'),('C','Cardiovascular'),('I','Interventions')],'Association européenne des interventions cardiovasculaires percutanées',
 '<p>Association de l’ESC consacrée à la cardiologie interventionnelle ; elle a publié des consensus sur les tests fonctionnels coronaires invasifs.</p>','i25-ifct')
a('COVADIS',[('CO','COronary (coronaire)'),('VA','VAsomotion (vasomotricité)'),('DIS','DISorders (troubles)')],'Groupe international d’étude des troubles de la vasomotricité coronaire',
 '<p>Groupe qui a proposé les critères diagnostiques de l’angor vasospastique et de l’angor microvasculaire.</p>','i25-vsa')
a('CIM-10',[('C','Classification'),('I','Internationale des'),('M','Maladies'),('10','dixième révision')],'Classification internationale des maladies, dixième révision',
 '<p>Classification de l’OMS ; la Suisse utilise pour le codage hospitalier la version allemande modifiée (CIM-10-GM).</p>')

# --- essais ---
t('ISCHEMIA',[('ISCHEMIA','nom d’essai arrangé à partir de « International Study of Comparative Health Effectiveness with Medical and Invasive Approaches », non strictement lettre à lettre')],'Essai ISCHEMIA (2020)','<p>Ischémie modérée à sévère : une stratégie invasive initiale n’a pas réduit les décès cardiovasculaires ni les infarctus par rapport au traitement médical optimal, mais a mieux soulagé l’angor.</p>')
