t('FAME',[('F','Fractional flow reserve (réserve coronaire fractionnelle)'),('A','versus Angiography for'),('M','Multivessel'),('E','Evaluation')],'Essais FAME (2009), FAME 2 (2012), FAME 3 (2022)','<p>FAME : angioplastie guidée par la FFR supérieure au guidage angiographique. FAME 2 : sténoses à FFR ≤ 0,80, moins de revascularisations urgentes avec l’angioplastie. FAME 3 : dans l’atteinte tritronculaire, l’angioplastie guidée par la FFR n’a pas été non inférieure au pontage à un an.</p>','i25-ffr')
t('DEFER',[('DEFER','nom d’essai anglais signifiant « différer » (report de l’angioplastie), non développable lettre à lettre')],'Étude DEFER (2001)','<p>Différer l’angioplastie d’une sténose à FFR non significative est sûr à long terme.</p>','i25-ffr')
t('DEFINE-FLAIR',[('DEFINE','nom d’essai (« définir »)'),('FLAIR','Functional Lesion Assessment of Intermediate stenosis to guide Revascularisation (évaluation fonctionnelle des sténoses intermédiaires)')],'Essai DEFINE-FLAIR (2017)','<p>Stratégie guidée par l’iFR non inférieure à la FFR à un an ; mortalité plus élevée dans le groupe iFR au suivi à 5 ans.</p>','i25-ifr')
t('iFR-SWEDEHEART',[('iFR','instantaneous wave-Free Ratio (rapport instantané sans onde)'),('SWEDEHEART','registre national suédois des maladies cardiaques, utilisé comme plateforme d’essai (nom arrangé, non strictement lettre à lettre)')],'Essai iFR-SWEDEHEART (2017)','<p>Stratégie guidée par l’iFR non inférieure à la FFR.</p>','i25-ifr')
t('SCOT-HEART',[('S','Scottish (écossais)'),('CO','COmputed'),('T','Tomography (tomodensitométrie)'),('HEART','of the HEART (du cœur)')],'Essai SCOT-HEART (2015 ; suivi à 5 ans 2018)','<p>Ajout du coroscanner au bilan de la douleur thoracique stable : moins de décès coronaires et d’infarctus non mortels à 5 ans.</p>','i25-ccta')
t('PROMISE',[('PROMISE','PROspective Multicenter Imaging Study for Evaluation of chest pain, non strictement lettre à lettre')],'Essai PROMISE (2015)','<p>Coroscanner et épreuve fonctionnelle en première intention : résultats cliniques semblables.</p>','i25-ccta')
t('DISCHARGE',[('DISCHARGE','Diagnostic Imaging Strategies for Patients With Stable Chest Pain and Intermediate Risk of Coronary Artery Disease, nom arrangé non strictement lettre à lettre')],'Essai DISCHARGE (2022)','<p>Probabilité intermédiaire : coroscanner et coronarographie invasive ont donné des événements semblables, avec moins de complications pour le scanner.</p>','i25-ccta')
t('CorMicA',[('Cor','Coronary (coronaire)'),('Mic','Microvascular (microvasculaire)'),('A','Angina (angor)')],'Essai CorMicA (2018)','<p>Chez des patients sans sténose obstructive, un traitement guidé par les tests fonctionnels invasifs a amélioré l’angor et la qualité de vie.</p>','i25-endotypes')
