t('AFIRE',[('AF','Atrial Fibrillation (fibrillation auriculaire)'),('I','and Ischemic events with'),('R','Rivaroxaban in'),('E','patiEnts with stable coronary artery disease')],'Essai AFIRE (2019)','<p>Fibrillation auriculaire et coronaropathie stable : rivaroxaban seul non inférieur à l’association avec un antiplaquettaire sur l’efficacité, et plus sûr.</p>')
t('COSIRA',[('CO','COronary'),('SI','SInus'),('R','Reducer for treatment of refractory'),('A','Angina')],'Essai COSIRA (2015)','<p>Réducteur du sinus coronaire comparé à une procédure simulée : amélioration de la classe d’angor.</p>','i25-reducer')
